<?php namespace App\Models; use Illuminate\Database\Eloquent\Factories\HasFactory; use Illuminate\Database\Eloquent\Model; class Work extends Model{use HasFactory; protected $fillable=['company_id','external_id','name','type','contractor','city','state_country','contract_value','status','potential','notes']; protected function casts():array{return ['contract_value'=>'decimal:2'];} public function company(){return $this->belongsTo(Company::class);}}
